import{_ as e,o as r,c as a,a0 as i}from"./chunks/framework.DQOulFGV.js";const p=JSON.parse('{"title":"What is Auditerra?","description":"","frontmatter":{},"headers":[],"relativePath":"docs/overview.md","filePath":"docs/overview.md"}'),o={name:"docs/overview.md"};function s(n,t,d,l,h,c){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="what-is-auditerra" tabindex="-1">What is Auditerra? <a class="header-anchor" href="#what-is-auditerra" aria-label="Permalink to &quot;What is Auditerra?&quot;">​</a></h1><p><strong>Auditerra</strong> is a soil diagnostics and restoration platform built for smallholder farmers in Kenya. It connects three key personas:</p><ol><li><strong>Farmers</strong> who report soil issues via USSD on basic feature phones</li><li><strong>Field Experts</strong> who conduct on-site diagnostics using an offline-first PWA</li><li><strong>Institutional Supervisors</strong> who monitor program impact through audit dashboards</li></ol><p>The platform transforms fragmented field observations into <strong>actionable restoration plans</strong> delivered directly to farmers via SMS.</p><h2 id="the-problem-we-solve" tabindex="-1">The Problem We Solve <a class="header-anchor" href="#the-problem-we-solve" aria-label="Permalink to &quot;The Problem We Solve&quot;">​</a></h2><h3 id="the-ground-truth-gap" tabindex="-1">The Ground-Truth Gap <a class="header-anchor" href="#the-ground-truth-gap" aria-label="Permalink to &quot;The Ground-Truth Gap&quot;">​</a></h3><p>Sub-Saharan Africa faces a catastrophic ecological crisis:</p><ul><li><strong>65%</strong> of arable land is actively degraded</li><li><strong>12 million hectares</strong> of productive land lost annually</li><li><strong>75 billion tons</strong> of fertile soil lost yearly</li></ul><p>Current monitoring relies on <strong>macro-level satellite data</strong>, which creates a <strong>ground-truth gap</strong>-failing to verify:</p><ul><li>Subsurface soil health (pH, nitrogen, phosphorus, potassium)</li><li>Localized socio-economic realities</li><li>Actual on-the-ground restoration progress</li></ul><h2 id="who-uses-auditerra" tabindex="-1">Who Uses Auditerra? <a class="header-anchor" href="#who-uses-auditerra" aria-label="Permalink to &quot;Who Uses Auditerra?&quot;">​</a></h2><h3 id="_1-farmers-primary-users" tabindex="-1">1. Farmers (Primary Users) <a class="header-anchor" href="#_1-farmers-primary-users" aria-label="Permalink to &quot;1. Farmers (Primary Users)&quot;">​</a></h3><ul><li>Tech comfort: Low (basic feature phone, 2G connectivity)</li><li>Pain points: <ul><li>Only realizes trees are dying when it&#39;s too late</li><li>Severe topsoil erosion and nutrient depletion</li><li>Isolated from centralized agricultural advice</li></ul></li></ul><p><strong>What they do:</strong></p><ul><li>Dial a USSD shortcode (<code>*384*55#</code>)</li><li>Register with their name, phone number, and location</li><li>Report issues (Soil, Water, Crop, Erosion)</li><li>Receive assistance from an agronomic expert</li><li>Receive AI-generated prescriptions via SMS with a 60 day retest to verify land progress</li></ul><h3 id="_2-field-experts-secondary-users" tabindex="-1">2. Field Experts (Secondary Users) <a class="header-anchor" href="#_2-field-experts-secondary-users" aria-label="Permalink to &quot;2. Field Experts (Secondary Users)&quot;">​</a></h3><ul><li>Tech comfort: High (smartphone user)</li><li>Pain points: <ul><li>Hardware damage from extreme heat (55°C+) and dust</li><li>No internet in remote areas</li><li>Difficulty tracking large, unmapped farm perimeters</li></ul></li></ul><p><strong>What they do:</strong></p><ul><li>Receive dispatch alerts on their PWA</li><li>Travel to farms and perform a <strong>Security Handshake</strong></li><li>Log GPS coordinates and soil diagnostics offline</li><li>Sync data automatically when signal returns</li><li>Receive AI recommendations in a report, and go for 60 day retest</li></ul><h3 id="_3-institutional-supervisors-tertiary-users" tabindex="-1">3. Institutional Supervisors (Tertiary Users) <a class="header-anchor" href="#_3-institutional-supervisors-tertiary-users" aria-label="Permalink to &quot;3. Institutional Supervisors (Tertiary Users)&quot;">​</a></h3><ul><li>Tech comfort: High</li><li>Pain points: <ul><li>Can&#39;t verify if experts actually visited farms</li><li>No centralized, aggregated field statistics</li><li>Difficulty justifying resource allocation to global funders</li></ul></li></ul><p><strong>What they do:</strong></p><ul><li>Monitor the Supervisor Dashboard</li><li>Track expert deployment densities</li><li>Audit 60-day re-test compliance</li><li>Export verifiable impact reports</li></ul><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><h3 id="_1-low-connectivity-first" tabindex="-1">1. Low-Connectivity First <a class="header-anchor" href="#_1-low-connectivity-first" aria-label="Permalink to &quot;1. Low-Connectivity First&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>USSD Interface</strong></td><td>Farmers report issues using basic feature phones. No internet required.</td></tr><tr><td><strong>Offline-First PWA</strong></td><td>Experts work in zero-connectivity zones. Data stores locally in IndexedDB.</td></tr><tr><td><strong>Background Sync</strong></td><td>Automatic data upload when network signal returns.</td></tr></tbody></table><h3 id="_2-verifiable-impact" tabindex="-1">2. Verifiable Impact <a class="header-anchor" href="#_2-verifiable-impact" aria-label="Permalink to &quot;2. Verifiable Impact&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Security Handshake</strong></td><td>4-digit code proves the expert physically visited the farm. Prevents fraud.</td></tr><tr><td><strong>60-Day Audit Loop</strong></td><td>Enforces re-testing. Measures biological survival, not just planting speed.</td></tr><tr><td><strong>Geospatial Boundary Mapping</strong></td><td>GPS polygons capture accurate farm perimeters.</td></tr></tbody></table><h3 id="_3-smart-matching" tabindex="-1">3. Smart Matching <a class="header-anchor" href="#_3-smart-matching" aria-label="Permalink to &quot;3. Smart Matching&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Multi-Factor Scoring</strong></td><td>Matches by proximity (40%), technical specialization (35%), language compatibility (15%).</td></tr><tr><td><strong>Dynamic Radius Expansion</strong></td><td>Searches 15km → 45km → unlimited until an expert is found.</td></tr><tr><td><strong>Language Compatibility</strong></td><td>Matches farmers with experts who speak their language (English/Kiswahili).</td></tr></tbody></table><h3 id="_4-ai-powered-diagnostics" tabindex="-1">4. AI-Powered Diagnostics <a class="header-anchor" href="#_4-ai-powered-diagnostics" aria-label="Permalink to &quot;4. AI-Powered Diagnostics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>RAG Processing</strong></td><td>Retrieval-Augmented Generation using Gemini Flash 3.6</td></tr><tr><td><strong>Three Output Streams</strong></td><td>Farmer SMS (160 chars), Expert Brief, Institutional Dashboard Metrics</td></tr><tr><td><strong>Continuous Learning</strong></td><td>60-day re-test cycle validates and improves AI accuracy</td></tr></tbody></table><h3 id="_5-institutional-oversight" tabindex="-1">5. Institutional Oversight <a class="header-anchor" href="#_5-institutional-oversight" aria-label="Permalink to &quot;5. Institutional Oversight&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Supervisor Dashboard</strong></td><td>Interactive national map with verified field data</td></tr><tr><td><strong>Audit-Ready Reports</strong></td><td>Immutable proof-of-impact for global climate funders</td></tr><tr><td><strong>Ticket Tracking</strong></td><td>Real-time status monitoring (PENDING → MATCHED → DISPATCHED → COMPLETED)</td></tr></tbody></table><hr><h2 id="how-it-works-the-four-step-workflow" tabindex="-1">How It Works: The Four-Step Workflow <a class="header-anchor" href="#how-it-works-the-four-step-workflow" aria-label="Permalink to &quot;How It Works: The Four-Step Workflow&quot;">​</a></h2><h3 id="step-1-report" tabindex="-1">Step 1: Report <a class="header-anchor" href="#step-1-report" aria-label="Permalink to &quot;Step 1: Report&quot;">​</a></h3><p><strong>Farmer dials <code>*384*55#</code></strong>(for example) and reports a soil/crop/water issue via USSD menu on their basic feature phone.</p><h3 id="step-2-match" tabindex="-1">Step 2: Match <a class="header-anchor" href="#step-2-match" aria-label="Permalink to &quot;Step 2: Match&quot;">​</a></h3><p><strong>Backend engine uses multi-factor scoring</strong> to find the nearest qualified expert (proximity + specialization + language) within a 15km radius.</p><h3 id="step-3-verify" tabindex="-1">Step 3: Verify <a class="header-anchor" href="#step-3-verify" aria-label="Permalink to &quot;Step 3: Verify&quot;">​</a></h3><p><strong>Expert travels to farm</strong>, enters the 4-digit Security Handshake code, logs GPS boundaries, and records soil diagnostics offline.</p><h3 id="step-4-prescribe" tabindex="-1">Step 4: Prescribe <a class="header-anchor" href="#step-4-prescribe" aria-label="Permalink to &quot;Step 4: Prescribe&quot;">​</a></h3><p><strong>Data syncs → AI generates prescription</strong> → SMS sent to farmer + dashboard updated + 60-day re-test scheduled.</p><hr><h2 id="key-metrics" tabindex="-1">Key Metrics <a class="header-anchor" href="#key-metrics" aria-label="Permalink to &quot;Key Metrics&quot;">​</a></h2><h3 id="north-star-metric" tabindex="-1">North Star Metric <a class="header-anchor" href="#north-star-metric" aria-label="Permalink to &quot;North Star Metric&quot;">​</a></h3><p><strong>Monthly Successful Farmer-Expert Matches</strong> — 300 matches/month target</p><h3 id="success-thresholds" tabindex="-1">Success Thresholds <a class="header-anchor" href="#success-thresholds" aria-label="Permalink to &quot;Success Thresholds&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Target</th></tr></thead><tbody><tr><td>Time-to-Match</td><td>≤ 24 hours</td></tr><tr><td>Expert Rejection Rate</td><td>≤ 15%</td></tr><tr><td>Security Handshake Success</td><td>≥ 98%</td></tr><tr><td>60-Day Audit Completion</td><td>≥ 80%</td></tr><tr><td>Farmer Repeat-Report Rate</td><td>≤ 5%</td></tr></tbody></table><hr><h2 id="technical-stack" tabindex="-1">Technical Stack <a class="header-anchor" href="#technical-stack" aria-label="Permalink to &quot;Technical Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Backend API</strong></td><td>FastAPI + Python</td><td>REST API, business logic</td></tr><tr><td><strong>Database</strong></td><td>PostgreSQL + PostGIS</td><td>Relational data, spatial queries</td></tr><tr><td><strong>ORM</strong></td><td>SQLAlchemy</td><td>Database abstraction, migrations</td></tr><tr><td><strong>AI</strong></td><td>Google Gemini 3.6 Flash</td><td>Diagnostic generation</td></tr><tr><td><strong>USSD</strong></td><td>Africa&#39;s Talking</td><td>Feature phone interface</td></tr><tr><td><strong>SMS</strong></td><td>SMS Leopard</td><td>Farmer prescriptions</td></tr><tr><td><strong>Frontend</strong></td><td>React + Next.js</td><td>PWA, Supervisor Dashboard</td></tr><tr><td><strong>Offline</strong></td><td>IndexedDB + Service Workers</td><td>Field data persistence</td></tr><tr><td><strong>Auth</strong></td><td>JWT</td><td>Role-based access control</td></tr><tr><td><strong>Hosting</strong></td><td>Backend: Heroku, Frontend: Vercel</td><td>Production deployment</td></tr></tbody></table><hr>',55)])])}const g=e(o,[["render",s]]);export{p as __pageData,g as default};
